mapper.select:
SELECT 
FROM coffee_log
WHERE member_id = #{memberId}

  AND (
    bean_name LIKE CONCAT('%', #{keyword}, '%')
    OR roastery LIKE CONCAT('%', #{keyword}, '%')
    OR origin_country LIKE CONCAT('%', #{keyword}, '%')
    OR taste_note LIKE CONCAT('%', #{keyword}, '%')
    OR memo LIKE CONCAT('%', #{keyword}, '%')
  )

AND drink_date >= #{from}
AND drink_date <= #{to}
ORDER BY drink_date DESC, coffee_log_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM coffee_log
WHERE coffee_log_id = #{coffeeLogId}
  AND member_id = #{memberId}

mapper.insert:
INSERT INTO coffee_log (
  member_id, bean_name, roastery, origin_country, region, process, roast_level,
  brew_method, water_temp, grind_size, brew_time, taste_note, acidity, sweetness,
  bitterness, body, aroma, memo, image_url, drink_date
)
VALUES (
  #{memberId}, #{beanName}, #{roastery}, #{originCountry}, #{region}, #{process}, #{roastLevel},
  #{brewMethod}, #{waterTemp}, #{grindSize}, #{brewTime}, #{tasteNote}, #{acidity}, #{sweetness},
  #{bitterness}, #{body}, #{aroma}, #{memo}, #{imageUrl}, #{drinkDate}
)

mapper.delete:
DELETE FROM coffee_log
WHERE coffee_log_id = #{coffeeLogId}
  AND member_id = #{memberId}

mapper.select:
SELECT drink_date, COUNT(*) AS log_count
FROM coffee_log
WHERE member_id = #{memberId}
  AND drink_date BETWEEN #{from} AND #{to}
GROUP BY drink_date
ORDER BY drink_date
